@push('scripts')
<script>
(()=>{const f=document.getElementById('freeze-form');if(!f)return;const all=document.getElementById('cf-all'),confirm=document.getElementById('cf-confirm'),enable=document.getElementById('cf-enable'),result=document.getElementById('cf-result');let version=0;f.addEventListener('change',e=>{if(e.target===confirm){enable.disabled=!confirm.checked;return;}version++;confirm.checked=false;confirm.disabled=true;enable.disabled=true;result.textContent='';});document.getElementById('cf-search').addEventListener('input',e=>{const norm=s=>s.replace(/[يى]/g,'ی').replace(/ك/g,'ک');const q=norm(e.target.value.trim());f.querySelectorAll('[data-category]').forEach(el=>el.hidden=!norm(el.dataset.category).includes(q));});document.getElementById('cf-preview').addEventListener('click',async()=>{const v=version;result.textContent='در حال بررسی…';try{const response=await fetch(@json(route('inventory-count-freeze.preview')),{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':f.querySelector('[name=_token]').value},body:new FormData(f)});const data=await response.json();if(v!==version)return;if(!response.ok)throw new Error(data.message||'بررسی انجام نشد.');result.textContent=`${data.products.toLocaleString('fa-IR')} کالا و بسته، ${data.reservation_rows.toLocaleString('fa-IR')} ردیف رزرو و ${data.orders.toLocaleString('fa-IR')} پیش‌فاکتور درگیر است. از این تعداد، ${data.historical_rows.toLocaleString('fa-IR')} ردیف تاریخی بدون تغییر موجودی بایگانی می‌شود. شمارش نهایی هنگام فعال‌سازی دوباره کنترل می‌شود.`;if(data.site_hold_count>0){result.textContent+=' سفارش‌های سایت مانع شروع: '+data.site_order_ids.map(n=>n.toLocaleString('fa-IR')).join('، ')+'؛ ابتدا سفارش پرداخت‌شده را به انبار وارد کنید یا دسته کوچک‌تری انتخاب کنید. هیچ سفارش سایت لغو نمی‌شود.';}confirm.disabled=!data.can_activate;}catch(e){result.textContent=e.message;confirm.disabled=true;}});f.addEventListener('submit',()=>{enable.disabled=true;enable.textContent='در حال فعال‌سازی و آزادسازی رزروها…';});})();
</script>
@endpush
